  -- --------------------------------------------- the tier assertions --
  select count(*) into v_count from public.academy_quiz_questions
   where app_slug = 'cashflow' and tier = 'intermediate';
  if v_count <> 132 then raise exception 'EC1 recut refused: the Professional tier holds % questions, expected 132', v_count; end if;

  select count(*) into v_count from public.academy_quiz_questions
   where app_slug = 'cashflow' and tier = 'intermediate' and not active;
  if v_count <> 0 then raise exception 'EC1 recut refused: % Professional question(s) are inactive', v_count; end if;

  select count(*) into v_count from (
    select scope, module_key, count(*) as n from public.academy_quiz_questions
     where app_slug = 'cashflow' and tier = 'intermediate' group by 1, 2
  ) b where (b.scope = 'module' and b.n <> 15) or (b.scope = 'final' and b.n <> 42);
  if v_count <> 0 then raise exception 'EC1 recut refused: % Professional bank(s) are not 15 (module) or 42 (final)', v_count; end if;

  -- Every option array is still four options and every key still points
  -- inside it: a rewritten options array that lost an entry would grade
  -- an answer that is no longer there.
  select count(*) into v_count from public.academy_quiz_questions
   where app_slug = 'cashflow' and tier = 'intermediate'
     and (jsonb_array_length(options) <> 4 or answer_index < 0 or answer_index >= jsonb_array_length(options));
  if v_count <> 0 then raise exception 'EC1 recut refused: % Professional question(s) have a bad option array or key index', v_count; end if;

  raise notice 'EC1 recut intermediate: % of 32 rows rewritten', v_updated;
end $$;

